<?php
declare(strict_types=1);
define('AUTH_KEY','FutProtec2026!');$DB_PATH=__DIR__.'/stats.db';
session_start();
if(isset($_POST['password'])){if($_POST['password']===AUTH_KEY){$_SESSION['auth_outbound']=true;header('Location: '.$_SERVER['PHP_SELF']);exit;}$loginError='Contrasena incorrecta';}
if(isset($_GET['logout'])){unset($_SESSION['auth_outbound']);session_destroy();header('Location: '.$_SERVER['PHP_SELF']);exit;}
if(!file_exists($DB_PATH)){echo'<div class="max-w-lg mx-auto mt-20 p-8 text-center font-sans"><h2 class="text-xl font-bold text-red-400">stats.db no encontrada</h2><p class="text-slate-400 mt-2">Ejecuta: <code class="bg-slate-800 px-2 py-1 rounded text-amber-400">php init_db.php</code></p></div>';exit;}
$db=new SQLite3($DB_PATH);$db->enableExceptions(true);$db->exec('PRAGMA journal_mode=WAL');$db->exec('PRAGMA busy_timeout=5000');
$action=$_POST['action']??$_GET['action']??'';
if($action==='update_lead'){header('Content-Type: application/json');try{$id=(int)($_POST['id']??0);$field=$_POST['field']??'';$value=$_POST['value']??'';$allowed=['estado_lead','persona_contacto','cargo_contacto','telefono_movil','telefono_fijo','tiene_whatsapp','observaciones'];if($id<=0||!in_array($field,$allowed,true)){echo json_encode(['ok'=>false]);exit;}if($field==='tiene_whatsapp')$value=$value?'1':'0';if($field==='observaciones'){$existing=$db->querySingle("SELECT observaciones FROM clubes_crm WHERE id={$id}");$ts=date('d/m H:i');$merged=$existing?$existing."\n[{$ts}] {$value}":"[{$ts}] {$value}";$stmt=$db->prepare("UPDATE clubes_crm SET observaciones=:val,ultimo_contacto=CURRENT_TIMESTAMP WHERE id=:id");$stmt->bindValue(':val',$merged,SQLITE3_TEXT);}elseif($field==='estado_lead'){$stmt=$db->prepare("UPDATE clubes_crm SET estado_lead=:val,ultimo_contacto=CURRENT_TIMESTAMP WHERE id=:id");$stmt->bindValue(':val',$value,SQLITE3_TEXT);}else{$stmt=$db->prepare("UPDATE clubes_crm SET {$field}=:val WHERE id=:id");$stmt->bindValue(':val',$value,SQLITE3_TEXT);}$stmt->bindValue(':id',$id,SQLITE3_INTEGER);$stmt->execute();echo json_encode(['ok'=>true]);}catch(\Exception $e){echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}exit;}
if($action==='update_config'){header('Content-Type: application/json');try{$k=$_POST['key']??'';$v=$_POST['value']??'';$stmt=$db->prepare("INSERT INTO config(clave,valor)VALUES(:k,:v)ON CONFLICT(clave)DO UPDATE SET valor=:v2");$stmt->bindValue(':k',$k,SQLITE3_TEXT);$stmt->bindValue(':v',$v,SQLITE3_TEXT);$stmt->bindValue(':v2',$v,SQLITE3_TEXT);$stmt->execute();echo json_encode(['ok'=>true]);}catch(\Exception $e){echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}exit;}
if($action==='get_lead'){header('Content-Type: application/json');$id=(int)($_GET['id']??0);$row=$db->querySingle("SELECT c.*,(SELECT COUNT(*)FROM envios e WHERE LOWER(e.email)=LOWER(c.email))as total_envios,(SELECT COUNT(*)FROM aperturas a JOIN envios e ON a.tracking_id=e.tracking_id WHERE LOWER(e.email)=LOWER(c.email))as total_aperturas FROM clubes_crm c WHERE c.id={$id}",true);echo json_encode($row?:null);exit;}
if($action==='save_template'){header('Content-Type: application/json');try{$id=(int)($_POST['id']??0);$a=$_POST['asunto']??'';$c=$_POST['cuerpo_html']??'';if($id>0){$stmt=$db->prepare("UPDATE plantillas SET asunto=:a,cuerpo_html=:c WHERE id=:id");$stmt->bindValue(':id',$id,SQLITE3_INTEGER);}else{$stmt=$db->prepare("INSERT INTO plantillas(nombre,asunto,cuerpo_html,activo)VALUES(:n,:a,:c,1)");$stmt->bindValue(':n','Plantilla Principal',SQLITE3_TEXT);}$stmt->bindValue(':a',$a,SQLITE3_TEXT);$stmt->bindValue(':c',$c,SQLITE3_TEXT);$stmt->execute();echo json_encode(['ok'=>true,'id'=>$id>0?$id:$db->lastInsertRowID()]);}catch(\Exception $e){echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}exit;}
if($action==='preview_template'){header('Content-Type: application/json');$tid=(int)($_GET['template_id']??0);$cid=(int)($_GET['club_id']??0);$tpl=$db->querySingle("SELECT asunto,cuerpo_html FROM plantillas WHERE id={$tid}",true);$club=$db->querySingle("SELECT * FROM clubes_crm WHERE id={$cid}",true);if($tpl&&$club){$asunto=str_replace(['{{CLUB}}','{{CONTACTO}}','{{FEDERACION}}','{{ANIO}}'],[$club['nombre_club'],$club['persona_contacto']?:'responsable',$club['federacion'],date('Y')],$tpl['asunto']);$cuerpo=str_replace(['{{CLUB}}','{{CONTACTO}}','{{FEDERACION}}','{{ANIO}}'],[$club['nombre_club'],$club['persona_contacto']?:'responsable',$club['federacion'],date('Y')],$tpl['cuerpo_html']);echo json_encode(['ok'=>true,'asunto'=>$asunto,'cuerpo_html'=>$cuerpo]);}else{echo json_encode(['ok'=>false,'error'=>'No encontrado']);}exit;}
if(empty($_SESSION['auth_outbound'])){$db->close();showLoginForm($loginError??'');exit;}
$config=[];$resCfg=$db->query("SELECT clave,valor FROM config");while($r=$resCfg->fetchArray(SQLITE3_ASSOC))$config[$r['clave']]=$r['valor'];
$motorActivo=($config['motor_estado']??'pausado')==='activo';$modoPruebas=($config['modo_entorno']??'test')==='test';
$totalLeads=(int)$db->querySingle("SELECT COUNT(*)FROM clubes_crm");$totalDups=(int)$db->querySingle("SELECT COUNT(*)FROM clubes_crm WHERE es_duplicado=1");
$totalEnviados=(int)$db->querySingle("SELECT COUNT(*)FROM envios WHERE estado='enviado'");
$totalAperturas=(int)$db->querySingle("SELECT COUNT(DISTINCT tracking_id)FROM aperturas");$tasaApertura=$totalEnviados>0?round(($totalAperturas/$totalEnviados)*100,1):0;
$smtpActivas=(int)$db->querySingle("SELECT COUNT(*)FROM cuentas_smtp WHERE activa=1");
$smtpEnviadosHoy=(int)$db->querySingle("SELECT COALESCE(SUM(enviados_hoy),0)FROM cuentas_smtp");
$estadosKanban=['Sin Contactar','Email Enviado / En Secuencia','Impactado / Abrio Email','En Conversacion / WhatsApp','Muestra / Propuesta Enviada','Cerrado Ganado','Cerrado Perdido'];
$kanbanData=[];$colClasses=['Sin Contactar'=>'border-slate-500','Email Enviado / En Secuencia'=>'border-blue-500','Impactado / Abrio Email'=>'border-cyan-500','En Conversacion / WhatsApp'=>'border-amber-500','Muestra / Propuesta Enviada'=>'border-purple-500','Cerrado Ganado'=>'border-emerald-500','Cerrado Perdido'=>'border-rose-500'];
foreach($estadosKanban as $est){$stmt=$db->prepare("SELECT c.*,(SELECT COUNT(*)FROM aperturas a JOIN envios e ON a.tracking_id=e.tracking_id WHERE LOWER(e.email)=LOWER(c.email))as num_opens FROM clubes_crm c WHERE c.estado_lead=:estado ORDER BY c.nombre_club ASC");$stmt->bindValue(':estado',$est,SQLITE3_TEXT);$res=$stmt->execute();$cards=[];while($row=$res->fetchArray(SQLITE3_ASSOC))$cards[]=$row;$kanbanData[$est]=$cards;}
$plantillas=[];$resTpl=$db->query("SELECT * FROM plantillas WHERE activo=1 ORDER BY id ASC");while($r=$resTpl->fetchArray(SQLITE3_ASSOC))$plantillas[]=$r;
$clubesList=[];$resClubes=$db->query("SELECT id,nombre_club,persona_contacto FROM clubes_crm ORDER BY nombre_club ASC LIMIT 500");while($r=$resClubes->fetchArray(SQLITE3_ASSOC))$clubesList[]=$r;
$federaciones=[];$resFed=$db->query("SELECT DISTINCT federacion FROM clubes_crm WHERE federacion!='' ORDER BY federacion ASC");while($r=$resFed->fetchArray(SQLITE3_ASSOC))$federaciones[]=$r['federacion'];
$estadisticasPorEstado=[];$resEst=$db->query("SELECT estado_lead,COUNT(*) as cnt FROM clubes_crm GROUP BY estado_lead ORDER BY cnt DESC");while($r=$resEst->fetchArray(SQLITE3_ASSOC))$estadisticasPorEstado[$r['estado_lead']]=(int)$r['cnt'];
$db->close();
function getWaLink(string $m):string{$n=explode(',',$m);$f=trim($n[0]??'');return($f!==''&&preg_match('/^[67]\d{8}$/',$f))?'https://wa.me/34'.$f:'';}
function escHtml(string $s):string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
$tplPlano=$plantillas[0]??null;$tplHtml=$plantillas[1]??null;
$tplActual=$tplPlano;
?><!DOCTYPE html><html lang="es" class="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>FutProtec — Outbound CRM</title>
