<div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><div class="flex items-center justify-between"><span class="text-slate-500 text-xs uppercase tracking-wider">Envios Hoy</span><i data-lucide="send" class="w-4 h-4 text-slate-600"></i></div><div class="text-2xl font-bold text-blue-400 mt-1 font-mono"><?=$smtpEnviadosHoy?></div><div class="text-xs text-slate-600 mt-1"><?=$smtpActivas?> cuentas SMTP activas</div></div>
<div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><div class="flex items-center justify-between"><span class="text-slate-500 text-xs uppercase tracking-wider">Tasa Apertura</span><i data-lucide="eye" class="w-4 h-4 text-slate-600"></i></div><div class="text-2xl font-bold text-cyan-400 mt-1 font-mono"><?=$tasaApertura?>%</div><div class="text-xs text-slate-600 mt-1"><?=$totalAperturas?> aperturas / <?=$totalEnviados?> envios</div></div>
