<div x-show="tab==='kanban'" x-cloak class="max-w-full mx-auto px-4 py-4"><div class="kanban-scroll flex gap-3 overflow-x-auto pb-4" style="min-height:60vh"><?php foreach($estadosKanban as $est):$cards=$kanbanData[$est]??[];$borderCls=$colClasses[$est]??'border-slate-500';?><div class="flex-shrink-0 w-72 bg-slate-900/50 border border-slate-800 rounded-xl p-3 flex flex-col"><div class="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3 px-1"><?=escHtml($est)?> <span class="text-slate-600">(<?=count($cards)?>)</span></div><div class="space-y-2 flex-1 overflow-y-auto max-h-[55vh]"><?php foreach($cards as $card):$waLink=getWaLink($card['telefono_movil']??'');$hasWa=(int)($card['tiene_whatsapp']??0);$opens=(int)($card['num_opens']??0);$isDup=(int)($card['es_duplicado']??0);$dupId=$card['duplicado_id']??null;?><div class="bg-slate-800 border-l-4 <?=$borderCls?> rounded-lg p-3 cursor-pointer hover:bg-slate-700/70 transition text-sm" @click="openLead(<?=$card['id']?>)"><div class="font-semibold text-slate-200 text-xs mb-1"><?=escHtml($card['nombre_club'])?></div><div class="flex items-center gap-2 flex-wrap text-[11px] text-slate-500"><?php if($card['persona_contacto']):?><span class="text-slate-400"><?=escHtml($card['persona_contacto'])?></span><?php endif;?><?php if($waLink&&$hasWa):?><a href="<?=escHtml($waLink)?>" target="_blank" @click.stop class="text-emerald-400 hover:text-emerald-300 font-semibold" title="WhatsApp"><i data-lucide="message-circle" class="w-3 h-3 inline"></i> WA</a><?php endif;?><?php if($opens>0):?><span class="bg-cyan-500/15 text-cyan-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold"><?=$opens?></span><?php endif;?><?php if($isDup):?><span class="bg-amber-500/15 text-amber-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold cursor-pointer" @click.stop="openMerge(<?=$dupId?>,<?=$card['id']?>)">DUPLICADO</span><?php endif;?></div></div><?php endforeach;?></div></div><?php endforeach;?></div></div>

<div x-show="tab==='gestor'" x-cloak class="max-w-full mx-auto px-4 py-4"><div class="flex items-center justify-between mb-3 flex-wrap gap-2"><h5 class="text-sm font-semibold text-slate-300">Gestor de Datos</h5><button @click="scanDups()" class="px-3 py-1.5 bg-amber-500/15 text-amber-400 border border-amber-500/30 rounded-lg text-xs font-semibold hover:bg-amber-500/25 transition flex items-center gap-1"><i data-lucide="search" class="w-3.5 h-3.5"></i> Escanear Duplicados</button></div><div class="flex gap-2 mb-3 flex-wrap"><input type="text" x-model="gs" @input="loadGestor()" placeholder="Buscar club o email..." class="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-slate-300 w-48 focus:outline-none focus:border-amber-500/50"><select x-model="ge" @change="loadGestor()" class="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="">Todos estados</option><?php foreach($estadosKanban as $es):?><option value="<?=escHtml($es)?>"><?=escHtml($es)?></option><?php endforeach;?></select><select x-model="gf" @change="loadGestor()" class="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="">Todas federaciones</option><?php foreach($federaciones as $fed):?><option value="<?=escHtml($fed)?>"><?=escHtml($fed)?></option><?php endforeach;?></select><select x-model="gpp" @change="gp=1;loadGestor()" class="bg-slate-800 border border-slate-700 rounded-lg px-2 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="10">10</option><option value="50" selected>50</option><option value="100">100</option><option value="250">250</option></select><span class="text-[11px] text-slate-600 self-center" x-text="gt"></span></div><div class="overflow-x-auto rounded-xl border border-slate-800"><table class="w-full text-xs"><thead><tr class="bg-slate-900 text-slate-400 text-[11px] uppercase tracking-wider"><th class="px-3 py-2 text-left cursor-pointer hover:text-slate-200" @click="gSort('nombre_club')">Club</th><th class="px-3 py-2 text-left cursor-pointer hover:text-slate-200 hidden md:table-cell" @click="gSort('email')">Email</th><th class="px-3 py-2 text-left hidden md:table-cell">Telefono</th><th class="px-3 py-2 text-left cursor-pointer hover:text-slate-200" @click="gSort('estado_lead')">Estado</th><th class="px-3 py-2 text-left hidden lg:table-cell">Federacion</th><th class="px-3 py-2 text-right">Accion</th></tr></thead><tbody id="gestorBody"><tr><td colspan="6" class="px-3 py-8 text-center text-slate-600">Cargando...</td></tr></tbody></table></div><div class="flex items-center justify-center gap-1 mt-3 flex-wrap" id="gestorP"></div></div>

<div x-show="tab==='editor'" x-cloak class="max-w-full mx-auto px-4 py-4"><div class="flex items-center gap-2 mb-3 flex-wrap"><button @click="cargarPreset('plano')" class="px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-xs font-semibold text-slate-300 hover:bg-slate-700 transition flex items-center gap-1"><i data-lucide="file-text" class="w-3.5 h-3.5"></i> Cargar Preset: Texto Plano (Email 1)</button><button @click="cargarPreset('html')" class="px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-xs font-semibold text-slate-300 hover:bg-slate-700 transition flex items-center gap-1"><i data-lucide="palette" class="w-3.5 h-3.5"></i> Cargar Preset: HTML Enriquecido (Email 2)</button><select x-model="tplTipo" @change="onTipoChange()" class="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="plano">Texto Plano</option><option value="html">HTML Enriquecido</option></select><span class="text-[11px] text-slate-600">Plantilla activa: <strong x-text="tplTipo==='plano'?'Email 1 — Texto Plano':'Email 2 — HTML Enriquecido'" class="text-amber-400"></strong></span></div><?php if($tplActual):?><div class="grid md:grid-cols-2 gap-4"><div><label class="text-[11px] uppercase tracking-wider text-slate-500 font-semibold">Asunto</label><input type="text" id="tplAsunto" value="<?=escHtml($tplActual['asunto'])?>" class="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-xs text-slate-300 mb-3 focus:outline-none focus:border-amber-500/50 font-mono"><label class="text-[11px] uppercase tracking-wider text-slate-500 font-semibold">Cuerpo <span x-text="tplTipo==='plano'?'(Texto Plano)':'(HTML)'" class="text-amber-400"></span></label><textarea id="tplCuerpo" class="w-full h-80 bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-xs text-slate-300 font-mono focus:outline-none focus:border-amber-500/50 resize-y"><?=escHtml($tplActual['cuerpo_html'])?></textarea><div class="flex gap-2 mt-2"><button @click="saveTpl()" class="px-4 py-1.5 bg-amber-500/20 text-amber-400 border border-amber-500/30 rounded-lg text-xs font-semibold hover:bg-amber-500/30 transition">Guardar Plantilla</button><span class="text-[11px] text-slate-600 self-center">Tags: {'{{CLUB}}'}, {'{{CONTACTO}}'}, {'{{FEDERACION}}'}, {'{{ANIO}}'}</span></div></div><div><label class="text-[11px] uppercase tracking-wider text-slate-500 font-semibold">Previsualizacion <span x-text="tplTipo==='plano'?'(Texto Plano)':'(HTML)'" class="text-amber-400"></span></label><select id="previewClub" class="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-xs text-slate-300 mb-2 focus:outline-none focus:border-amber-500/50"><option value="">-- Seleccionar club --</option><?php foreach($clubesList as $c):?><option value="<?=$c['id']?>"><?=escHtml($c['nombre_club'].($c['persona_contacto']?' ('.$c['persona_contacto'].')':''))?></option><?php endforeach;?></select><button @click="previewTpl()" class="px-4 py-1.5 bg-slate-800 border border-slate-700 rounded-lg text-xs text-slate-300 hover:bg-slate-700 transition mb-3 w-full">Previsualizar</button><div id="previewWrapper" x-show="tplTipo==='plano'"><div id="previewTextoPlano" class="w-full p-4 border border-slate-700 rounded-lg bg-white text-slate-800 text-sm font-mono whitespace-pre-wrap" style="min-height:200px;display:none;"></div></div><iframe id="previewIframe" x-show="tplTipo==='html'" class="w-full h-[500px] border border-slate-700 rounded-lg bg-white" srcdoc="<html><body style='display:flex;align-items:center;justify-content:center;height:100%;color:#94a3b8;font-family:sans-serif;'>Selecciona un club y pulsa Previsualizar</body></html>"></iframe></div></div><?php else:?><p class="text-slate-500 text-sm">No hay plantillas.</p><?php endif;?></div>

