</div><div class="bg-slate-800 border border-slate-700 rounded-xl p-3 mb-3 space-y-2"><label class="text-[11px] text-slate-500 uppercase tracking-wider">Campos a conservar:</label><template x-for="f in mf" :key="f.name"><div class="flex items-center gap-3 text-xs"><span class="w-16 text-slate-500 text-[11px] uppercase" x-text="f.label"></span><label class="flex items-center gap-1 text-slate-300"><input type="radio" :name="'mg_'+f.name" value="A" :checked="f.cA" class="w-3 h-3 accent-amber-500"><span class="text-[11px]" x-text="'A: '+(f.vA||'vacio')"></span></label><label class="flex items-center gap-1 text-slate-300"><input type="radio" :name="'mg_'+f.name" value="B" :checked="!f.cA" class="w-3 h-3 accent-amber-500"><span class="text-[11px]" x-text="'B: '+(f.vB||'vacio')"></span></label></div></template></div><label class="flex items-center gap-2 text-xs text-slate-400 mb-3"><input type="checkbox" x-model="mn" class="w-3 h-3 accent-amber-500">Fusionar notas de seguimiento</label><div class="flex gap-2"><button @click="mm=false" class="px-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-xs text-slate-400 hover:bg-slate-700 transition">Cancelar</button><button @click="doMerge()" class="px-4 py-2 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-lg text-xs font-semibold hover:bg-emerald-500/30 transition">Fusionar y Eliminar Duplicado</button></div></div></div></div>

