mber" x-model="sf.limite_diario" class="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div></div><div class="flex gap-2 pt-2"><button @click="sm=false" class="flex-1 px-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-xs text-slate-400 hover:bg-slate-700 transition">Cancelar</button><button @click="saveSmtp()" class="flex-1 px-4 py-2 bg-blue-500/20 text-blue-400 border border-blue-500/30 rounded-lg text-xs font-semibold hover:bg-blue-500/30 transition">Guardar</button></div></div></div></div>

<script>function app(){return{
tab:'kanban',killSwitch:<?=$motorActivo?'true':'false'?>,modeTest:<?=$modoPruebas?'true':'false'?>,
tplTipo:'plano',presetPlanoId:1,presetHtmlId:2,
lm:false,mm:false,sm:false,ln:'',mn:true,mk:0,md:0,
ld:{},mf:[],mha:'',mhb:'',
se:0,sf:{email:'',host:'mail.getfutprotec.com',puerto:465,usuario:'',password:'',seguridad:'ssl',limite_diario:50},
gs:'',ge:'',gf:'',gt:'',gp:1,gpp:50,gsc:'nombre_club',gso:'ASC',
get waLink(){const m=this.ld.telefono_movil||'';const n=m.split(',').map(s=>s.trim()).filter(s=>/^[67]\d{8}$/.test(s));return n.length>0?'https://wa.me/34'+n[0]:'';},
async boot(){window.__app=this;lucide.createIcons();await this.loadGestor();await this.loadSmtp()},
async toggleWa(){this.ld.tiene_whatsapp=!this.ld.tiene_whatsapp;await this.saveF('tiene_whatsapp',this.ld.tiene_whatsapp?1:0)},
async toggleKS(){this.killSwitch=!this.killSwitch;const f=new FormData();f.append('action','update_config');f.append('key','motor_estado');f.append('value',this.killSwitch?'activo':'pausado');await fetch('',{method:'POST',body:f})},
async toggleModo(){this.modeTest=!this.modeTest;const f=new FormData();f.append('action','update_config');f.append('key','modo_entorno');f.append('value',this.modeTest?'test':'produccion');await fetch('',{method:'POST',body:f})},

async openLead(id){const r=await fetch('?action=get_lead&id='+id);this.ld=await r.json();this.ln='';this.ld.tiene_whatsapp=!!(+this.ld.tiene_whatsapp);this.lm=true;setTimeout(()=>lucide.createIcons(),100)},
async saveF(field,value){if(!this.ld.id)return;const f=new FormData();f.append('action','update_lead');f.append('id',this.ld.id);f.append('field',field);f.append('value',value);await fetch('',{method:'POST',body:f})},
async addNota(){if(!this.ln.trim())return;await this.saveF('observaciones',this.ln);const r=await fetch('?action=get_lead&id='+this.ld.id);this.ld=await r.json();this.ln=''},

async openMerge(k,d){this.mk=k;this.md=d;const[r1,r2]=await Promise.all([fetch('?action=get_lead&id='+k).then(r=>r.json()),fetch('?action=get_lead&id='+d).then(r=>r.json())]);const a=r1,b=r2;if(!a||!b)return;this.mha=this.fr('Club',a.nombre_club)+this.fr('Email',a.email)+this.fr('Fed',a.federacion||'')+this.fr('Contacto',a.persona_contacto)+this.fr('Movil',a.telefono_movil)+this.fr('Fijo',a.telefono_fijo)+this.fr('Estado',a.estado_lead)+'<div class="mt-1"><strong class="text-slate-500 text-[11px]">Notas:</strong><br>'+this.esc(a.observaciones||'(sin notas)')+'</div>';this.mhb=this.fr('Club',b.nombre_club)+this.fr('Email',b.email)+this.fr('Fed',b.federacion||'')+this.fr('Contacto',b.persona_contacto)+this.fr('Movil',b.telefono_movil)+this.fr('Fijo',b.telefono_fijo)+this.fr('Estado',b.estado_lead)+'<div class="mt-1"><strong class="text-slate-500 text-[11px]">Notas:</strong><br>'+this.esc(b.observaciones||'(sin notas)')+'</div>';this.mf=[{name:'nombre',label:'Nombre',vA:a.nombre_club,vB:b.nombre_club,cA:true},{name:'contacto',label:'Contacto',vA:a.persona_contacto,vB:b.persona_contacto,cA:!!a.persona_contacto},{name:'movil',label:'Movil',vA:a.telefono_movil,vB:b.telefono_movil,cA:!!a.telefono_movil},{name:'fijo',label:'Fijo',vA:a.telefono_fijo,vB:b.telefono_fijo,cA:!!a.telefono_fijo},{name:'estado',label:'Estado',vA:a.estado_lead,vB:b.estado_lead,cA:true}];this.mm=true;this.mn=true;setTimeout(()=>lucide.createIcons(),100)},
fr(label,val){return'<div><strong class="text-slate-500 text-[11px]">'+label+':</strong> '+this.esc(val||'-')+'</div>'},
async doMerge(){const fm={nombre:'nombre_club',contacto:'persona_contacto',movil:'telefono_movil',fijo:'telefono_fijo',estado:'estado_lead'};for(const f of this.mf){const s=document.querySelector('input[name="mg_'+f.name+'"]:checked');if(s&&s.value==='B'){const fd=new FormData();fd.append('action','update_lead');fd.append('id',this.mk);fd.append('field',fm[f.name]);const bL=await fetch('?action=get_lead&id='+this.md).then(r=>r.json());fd.append('value',bL[fm[f.name]]||'');await fetch('',{method:'POST',body:fd})}}const fd=new FormData();fd.append('action','merge_leads');fd.append('keep_id',this.mk);fd.append('dup_id',this.md);fd.append('merge_notes',this.mn?'1':'0');const r=await fetch('api_leads.php',{method:'POST',body:fd});const j=await r.json();if(j.ok){this.mm=false;location.reload()}else{alert('Error: '+(j.error||'Desconocido'))}},

async scanDups(){const r=await fetch('api_leads.php?action=scan_duplicates');const j=await r.json();if(j.ok){alert('Escaneo: '+j.dups+' duplicados en '+j.total+' clubes.');location.reload()}else{alert('Error: '+(j.error||'Desconocido'))}},

async loadGestor(){const A=window.__app||this;const p=new URLSearchParams({action:'get_leads_table',page:A.gp,per_page:A.gpp,sort:A.gsc,order:A.gso,search:A.gs,estado:A.ge,federacion:A.gf});const r=await fetch('api_leads.php?'+p.toString());const j=await r.json();if(!j.ok)return;A.gt=j.total+' resultados';let h='';j.data.forEach(l=>{h+='<tr class="border-b border-slate-800/50 hover:bg-slate-800/30 transition"><td class="px-3 py-2"><span class="font-medium text-slate-300">'+A.esc(l.nombre_club)+'</span>'+(l.es_duplicado==1?' <span class="bg-amber-500/15 text-amber-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold cursor-pointer" onclick="window.__app.openMerge('+l.duplicado_id+','+l.id+')" title="Fusionar duplicado">⚠️ DUPLICADO</span>':'')+'</td><td class="px-3 py-2 hidden md:table-cell"><code class="text-[11px] text-slate-500">'+A.esc(l.email)+'</code></td><td class="px-3 py-2 hidden md:table-cell text-[11px] text-slate-400 font-mono">'+A.esc(l.telefono_movil||'-')+'</td><td class="px-3 py-2 text-[11px] text-slate-400">'+A.esc(l.estado_lead)+'</td><td class="px-3 py-2 hidden lg:table-cell text-[11px] text-slate-600">'+A.esc(l.federacion||'')+'</td><td class="px-3 py-2 text-right"><button class="px-2 py-1 bg-slate-800 border border-slate-700 rounded text-[11px] text-slate-400 hover:text-slate-200 hover:border-slate-600 transition" onclick="window.__app.openLead('+l.id+')" title="Abrir ficha del club">Ficha</button></td></tr>'});document.getElementById('gestorBody').innerHTML=h||'<tr><td colspan="6" class="px-3 py-8 text-center text-slate-600">Sin resultados</td></tr>';let pg='';const tp=j.total_pages;const cp=A.gp;let s=Math.max(1,cp-2);let e=Math.min(tp,cp+2);if(s>1){pg+=bpg(1);if(s>2)pg+='<span class="px-1 text-slate-600">…</span>'}for(let i=s;i<=e;i++)pg+=bpg(i);if(e<tp){if(e<tp-1)pg+='<span class="px-1 text-slate-600">…</span>';pg+=bpg(tp)}document.getElementById('gestorP').innerHTML=pg;
function bpg(n){return'<button class="px-2 py-0.5 text-[11px] rounded border '+(n===A.gp?'bg-slate-700 border-slate-600 text-slate-200':'border-slate-800 text-slate-500 hover:text-slate-300')+'" onclick="window.__app.gp='+n+';window.__app.loadGestor()" title="Ir a pagina '+n+'">'+n+'</button>'}},
gSort(col){if(this.gsc===col)this.gso=this.gso==='ASC'?'DESC':'ASC';else{this.gsc=col;this.gso='ASC'}this.gp=1;this.loadGestor()},

async saveTpl(){const a=document.getElementById('tplAsunto').value;const c=document.getElementById('tplCuerpo').value;const tid=this.tplTipo==='plano'?this.presetPlanoId:this.presetHtmlId;const f=new FormData();f.append('action','save_template');f.append('id',tid);f.append('asunto',a);f.append('cuerpo_html',c);const r=await fetch('',{method:'POST',body:f});const j=await r.json();alert(j.ok?'Plantilla guardada (ID '+j.id+')':'Error: '+(j.error||'Desconocido'))},
async previewTpl(){const ci=document.getElementById('previewClub').value;if(!ci){alert('Selecciona un club');return}const tid=this.tplTipo==='plano'?this.presetPlanoId:this.presetHtmlId;const r=await fetch('?action=preview_template&template_id='+tid+'&club_id='+ci);const j=await r.json();if(!j.ok){alert('Error: '+(j.error||'Desconocido'));return}const iframe=document.getElementById('previewIframe');const textoDiv=document.getElementById('previewTextoPlano');if(this.tplTipo==='html'){if(iframe)iframe.srcdoc=j.cuerpo_html}else{if(textoDiv){textoDiv.style.display='block';textoDiv.textContent=j.cuerpo_html;if(iframe)iframe.style.display='none'}}},
onTipoChange(){this.cargarPreset(this.tplTipo)},
async cargarPreset(tipo){this.tplTipo=tipo;const tid=tipo==='plano'?this.presetPlanoId:this.presetHtmlId;try{const r=await fetch('?action=preview_template&template_id='+tid+'&club_id=1');const j=await r.json();if(j.ok){document.getElementById('tplAsunto').value=j.asunto||'';document.getElementById('tplCuerpo').value=j.cuerpo_html||'';const iframe=document.getElementById('previewIframe');const textoDiv=document.getElementById('previewTextoPlano');if(tipo==='plano'){if(textoDiv){textoDiv.style.display='none'}if(iframe)iframe.srcdoc='<html><body style="display:flex;align-items:center;justify-content:center;height:100%;color:#94a3b8;font-family:sans-serif;">Selecciona un club y pulsa Previsualizar</body></html>'}else{if(textoDiv){textoDiv.style.display='none'}if(iframe)iframe.srcdoc='<html><body style="display:flex;align-items:center;justify-content:center;height:100%;color:#94a3b8;font-family:sans-serif;">Selecciona un club y pulsa Previsualizar</body></html>'}}else{const presets=this.getPresets();document.getElementById('tplAsunto').value=presets[tipo].asunto;document.getElementById('tplCuerpo').value=presets[tipo].cuerpo}}catch(e){const presets=this.getPresets();document.getElementById('tplAsunto').value=presets[tipo].asunto;document.getElementById('tplCuerpo').value=presets[tipo].cuerpo}},
getPresets(){return{plano:{asunto:"Consulta equipacion / cantera {{CLUB}}",cuerpo:"Hola, {{CONTACTO}}.\n\nTe escribo directamente porque estamos preparando el material de proteccion y espinilleras personalizadas para la temporada de varios clubes de la zona y queria consultar con quien puedo revisar el tema de la cantera en el {{CLUB}}.\n\nHemos disenado un modelo de equipacion/reventa de espinilleras con marcado CE que permite al club generar un margen de beneficio directo (hasta el 100%) para financiar gastos de la temporada, sin que el club tenga que adelantar presupuesto.\n\nTendrias 2 minutos esta semana para comentarlo brevemente o te encargas tu de esta parte?\n\nUn saludo,\nRodrigo Vazquez\nSocio Co-Fundador & Estratega de Ventas | FutProtec"},html:{asunto:"Material Deportivo Personalizado para {{CLUB}}",cuerpo:"<div style=\"font-family: Arial, sans-serif; color: #1e293b; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;\">\n  <div style=\"background-color: #0f172a; padding: 20px; text-align: center;\">\n    <h2 style=\"color: #ffffff; margin: 0; font-size: 20px;\">FutProtec | Material Deportivo para {{CLUB}}</h2>\n  </div>\n  <div style=\"padding: 24px; background-color: #ffffff;\">\n    <p style=\"font-size: 15px; color: #334155;\">Hola, <strong>{{CONTACTO}}</strong>:</p>\n    <p style=\"font-size: 14px; color: #475569; line-height: 1.6;\">\n      Como te comentaba, en FutProtec ayudamos a los clubes de futbol base a equipar a sus jugadores con espinilleras personalizadas de alta resistencia (Certificacion CE) y, al mismo tiempo, crear una via de ingresos extra para el club.\n    </p>\n    \n    <div style=\"background-color: #f8fafc; border-left: 4px solid #10b981; padding: 16px; margin: 20px 0; border-radius: 4px;\">\n      <h4 style=\"margin: 0 0 8px 0; color: #0f172a;\">Beneficios clave para el {{CLUB}}:</h4>\n      <ul style=\"margin: 0; padding-left: 20px; color: #334155; font-size: 14px;\">\n        <li><strong>Sin riesgo financiero:</strong> Gestion simplificada de pedidos y tallas combinadas.</li>\n        <li><strong>Alto margen:</strong> Hasta el 100% de beneficio segun volumen de cantera.</li>\n        <li><strong>Diseno exclusivo:</strong> Impresion con el escudo y colores corporativos del club.</li>\n      </ul>\n    </div>\n\n    <div style=\"text-align: center; margin: 28px 0;\">\n      <a href=\"https://futprotec.com/catalogo\" style=\"background-color: #2563eb; color: #ffffff; text-decoration: none; padding: 12px 24px; border-radius: 6px; font-weight: bold; font-size: 14px; display: inline-block;\">Ver Catalogo y Galeria de Disenos</a>\n    </div>\n\n    <p style=\"font-size: 13px; color: #64748b; line-height: 1.5;\">\n      Quedo a tu disposicion si quereis ver una muestra fisica o hacer una simulacion de ingresos para la cantera.\n    </p>\n  </div>\n  <div style=\"background-color: #f1f5f9; padding: 16px; text-align: center; font-size: 12px; color: #94a3b8;\">\n    FutProtec — Proteccion Oficial Futbol Base\n  </div>\n</div>"}}},

async loadSmtp(){const A=window.__app||this;const r=await fetch('api_smtp.php?action=get_accounts');const j=await r.json();if(!j.ok)return;let h='';j.accounts.forEach(a=>{const testBtn='<button class="px-2 py-1 bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 rounded text-[11px] hover:bg-cyan-500/20 transition relative" onclick="window.__app.testSmtp('+a.id+',this)" title="Test conexion SMTP"><i data-lucide="zap" class="w-3 h-3"></i></button>';h+='<tr class="border-b border-slate-800/50 hover:bg-slate-800/30 transition"><td class="px-3 py-2"><code class="text-[11px] text-slate-300">'+A.esc(a.email)+'</code></td><td class="px-3 py-2 hidden sm:table-cell text-[11px] text-slate-500">'+A.esc(a.host)+':'+a.puerto+'</td><td class="px-3 py-2 text-center text-[11px]"><span class="text-slate-300 font-semibold">'+a.enviados_hoy+'</span><span class="text-slate-600"> / '+a.limite_diario+'</span></td><td class="px-3 py-2 text-center">'+(a.activa==1?'<span class="bg-emerald-500/15 text-emerald-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold">ON</span>':'<span class="bg-slate-700 text-slate-500 px-1.5 py-0.5 rounded-full text-[10px] font-semibold">OFF</span>')+' '+(a.ultimo_error?'<span class="bg-rose-500/15 text-rose-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold cursor-help" title="'+A.esc(a.ultimo_error)+'">!</span>':'<span class="bg-emerald-500/15 text-emerald-400 px-1.5 py-0.5 rounded-full text-[10px] font-semibold">OK</span>')+'</td><td class="px-3 py-2 text-right"><div class="flex gap-1 justify-end">'+testBtn+'<button class="px-2 py-1 bg-amber-500/10 text-amber-400 border border-amber-500/20 rounded text-[11px] hover:bg-amber-500/20 transition" onclick="window.__app.toggleSmtp('+a.id+')" title="Activar/Desactivar cuenta"><i data-lucide="power" class="w-3 h-3"></i></button><button class="px-2 py-1 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded text-[11px] hover:bg-blue-500/20 transition" onclick="window.__app.openSmtp('+a.id+')" title="Editar cuenta SMTP"><i data-lucide="pencil" class="w-3 h-3"></i></button><button class="px-2 py-1 bg-rose-500/10 text-rose-400 border border-rose-500/20 rounded text-[11px] hover:bg-rose-500/20 transition" onclick="window.__app.deleteSmtp('+a.id+')" title="Eliminar cuenta SMTP"><i data-lucide="trash-2" class="w-3 h-3"></i></button></div></td></tr>'});document.getElementById('smtpBody').innerHTML=h||'<tr><td colspan="5" class="px-3 py-8 text-center text-slate-600">Sin cuentas</td></tr>';setTimeout(()=>lucide.createIcons(),50)},
async openSmtp(id){this.se=id;if(id>0){const r=await fetch('api_smtp.php?action=get_accounts');const j=await r.json();const a=j.accounts.find(x=>x.id==id);if(a){this.sf={email:a.email,host:a.host,puerto:a.puerto,usuario:a.usuario,password:a.password,seguridad:a.seguridad,limite_diario:a.limite_diario}}}else{this.sf={email:'',host:'mail.getfutprotec.com',puerto:465,usuario:'',password:'',seguridad:'ssl',limite_diario:50}}this.sm=true;setTimeout(()=>lucide.createIcons(),100)},
async saveSmtp(){const f=new FormData();f.append('action','save_account');if(this.se>0)f.append('id',this.se);f.append('email',this.sf.email);f.append('host',this.sf.host);f.append('puerto',this.sf.puerto);f.append('usuario',this.sf.usuario);f.append('password',this.sf.password);f.append('seguridad',this.sf.seguridad);f.append('limite_diario',this.sf.limite_diario);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();if(j.ok){this.sm=false;this.loadSmtp()}else{alert('Error: '+(j.error||'Desconocido'))}},
async toggleSmtp(id){const f=new FormData();f.append('action','toggle_account');f.append('id',id);await fetch('api_smtp.php',{method:'POST',body:f});this.loadSmtp()},
async deleteSmtp(id){if(!confirm('Eliminar esta cuenta SMTP?'))return;const f=new FormData();f.append('action','delete_account');f.append('id',id);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();if(j.ok)this.loadSmtp();else alert('Error: '+(j.error||'Desconocido'))},
async testSmtp(id,btn){if(btn){btn.disabled=true;const orig=btn.innerHTML;btn.innerHTML='<span class="w-3 h-3 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin inline-block"></span>'}const f=new FormData();f.append('action','test_smtp');f.append('id',id);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();const ok=j.status==='success';alert((ok?'CONEXION EXITOSA: ':'ERROR: ')+j.message);if(btn){btn.disabled=false;btn.innerHTML=orig}this.loadSmtp()},

esc(s){const d=document.createElement('div');d.textContent=s||'';return d.innerHTML}}}
</script></body></html>
<?php function showLoginForm(string $error=''):void{?><!DOCTYPE html><html lang="es" class="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>FutProtec — Acceso Panel</title><script src="https://cdn.tailwindcss.com"></script><script>tailwind.config={darkMode:'class'}</script><style>body{font-family:'Inter',system-ui,sans-serif}</style></head><body class="bg-slate-950 min-h-screen flex items-center justify-center"><div class="bg-slate-900 border border-slate-800 rounded-2xl p-8 w-full max-w-sm shadow-2xl"><div class="text-center mb-6"><div class="text-2xl font-bold text-amber-400">FutProtec</div><p class="text-slate-500 text-xs mt-1">Panel CRM Kanban v2.0</p></div><?php if($error):?><div class="bg-rose-500/10 border border-rose-500/30 rounded-lg px-3 py-2 text-rose-400 text-xs text-center mb-4"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="mb-4"><label class="text-[10px] text-slate-500 uppercase tracking-wider">Contrasena</label><input type="password" name="password" class="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 text-center mt-1 focus:outline-none focus:border-amber-500/50" placeholder="........" required autofocus></div><button type="submit" class="w-full py-2.5 bg-amber-500/20 text-amber-400 border border-amber-500/30 rounded-lg text-sm font-semibold hover:bg-amber-500/30 transition">Acceder al Panel</button></form></div></body></html><?php }?>